import sys

def main():
    cubos = list(map(int, sys.stdin.read().split()))
    if not cubos:
        return

    total = sum(cubos)
    if total % 3 != 0:
        print('N')
        return

    target = total // 3

    if target not in cubos:
        print('N')
        return

    # Remove um cubo correspondente ao topo
    cubos.remove(target)

    # Verifica se existem dois cubos restantes cuja soma seja o target
    n = len(cubos)
    for i in range(n):
        for j in range(i + 1, n):
            if cubos[i] + cubos[j] == target:
                print('S')
                return

    print('N')

if __name__ == '__main__':
    main()
